var marginTop, path = 'https://www.prisma.cat/';

function mostrarHeaderFooter() {
	$.ajax({
		async: !0,
		url: path + "ajax/mostrar_header_2.php",
		cache: !0,
		type: "GET",
		success: function(pagina) {
			$("header").html(pagina);
			$('.closebtn').css('display', 'none');
			if (/Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent)) {
				$('.navbar-nav > li').addClass('mobile');
			} else {
				$('.navbar-nav > li').addClass('computer');
			}
			$('.prisma-header').on('focus', '.form-control', function() {
				$(this).next().next().addClass('active');
			});
			$('.prisma-header').on('blur', '.form-control', function() {
				if ($(this).val().trim() == '')
					$(this).next().next().removeClass('active');
			});
		}
	});
	$.ajax({
		async: !0,
		url: path + "ajax/mostrar_footer_2.php",
		cache: !0,
		type: "GET",
		success: function(pagina) {
			$("footer").html(pagina);

			$('.form-footer').on('focus', '.form-control', function() {
				$('.form-footer label').hide();
			});
			$('.form-footer').on('blur', '.form-control', function() {
				if ($('#adreca-electronica').val().trim() == '')
					$('.form-footer label').show();
			});

			function mostrarErrorButlleti(missatgeError) {
				$('#modalErrorBody').html(missatgeError);
				$('#modalError').modal('show')
			}

			function mostrarSuccessButlleti(missatgeSuccess) {
				$('#modalOkBody').html(missatgeSuccess);
				$('#modalOK').modal('show');
			}

			function validacioCorreuButlleti() {
				var email = $('#adreca-electronica').val().trim();
				var error = "";
				if (email.length != 0) {
					var tfld_email = $.trim(email);
					var emailFilter = /^([\w-\.]+@([\w-]+\.)+[\w-]{2,4})?$/;
					var illegalChars = /[\(\)\<\>\,\;\:\\\"\[\]]/;
					if (!emailFilter.test(tfld_email)) {
						error = "El correu electr\u00F2nic no és v\u00E0lid";
					} else if (email.match(illegalChars)) {
						error = "El correu electr\u00F2nic té car\u0E0cters no permesos";
					}
				} else
					error = "Cal omplir el camp";
				return error;
			}

			$('.form-footer').on('click', '#news', function() {
				if (validacioCorreuButlleti() != '') {
					var missatgeError = "<p>Cal omplir el camp de l'adreça electrònica.</p>";
					mostrarErrorButlleti(missatgeError);
				} else {
					var correu = $('#adreca-electronica').val().trim();
					var comprovaSpam = $("#butlletiSpam").val().trim();
					$.ajax({
						url: path + "ajax/mailingNou.php?correu=" + correu +
							"&comprova" + comprovaSpam,
						cache: !1,
						type: "GET",
						success: function(message) {
							if (message == "ok") {
								var missatgeConsultaOK = "<p>T'has subscrit correctament al nostre butlletí electrònic.</p>";
								missatgeConsultaOK += "<p>En breu rebràs un missatge de confirmació en del correu ";
								missatgeConsultaOK += "<strong><span class='correu_consulta'>" + correu + "</span></strong>.</p>";
								missatgeConsultaOK += "<p>Si el missatge no arriba en 15 minuts, revisa la carpeta del correu brossa. ";
								missatgeConsultaOK += "<p>Gr&agrave;cies per confiar en PrisMa!</p>";
								mostrarSuccessButlleti(missatgeConsultaOK)
							} else {
								mostrarErrorButlleti(message)
							}
						}
					})
				}
			});

			function checkAcceptCookies() {
				if (localStorage.getItem("acceptCookies") == 'true') {
					$('#cntCookies').hide();
				}
			}
			checkAcceptCookies();
		}
	})
}

function acceptCookies() {
	localStorage.setItem("acceptCookies", "true");
	$('#cntCookies').slideUp();
}
mostrarHeaderFooter();
var urlPagina = window.location.pathname.split('?')[0];
if (urlPagina.substr(-1) == "/") urlPagina = urlPagina.substr(0, urlPagina.length - 1);
var dispositiu;
if (/Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent)) {
	dispositiu = "mobil";
	$('#boto-tancar').css('display', 'none');
	$('#top-menu').remove()
} else {
	dispositiu = "ordinador"
}

function efectuarPagament() {
	var codiCurs = $("#codiCurs").html().trim(),
		 titol = $("#titol").html().trim(),
		 dni = $("#dni").html().trim(),
		 nomTit = $("#nom-titular").html().trim(),
		 nomAl = $("#nom-alumne").html().trim(),
		 importPag = $("#import").html().trim(),
		 importPagat = $("#importPagat").html().trim(),
		 frac = $("#frac").html().trim(),
		 email = $("#email").html().trim();

 	if (frac=='0') preu=importPag;
	else preu=importPagat;

	if (codiCurs!='' && titol!='' && dni!='' && nomTit!='' && nomAl!='' && importPag!='') {
		$("#form_enviar_dades").click(function(e) {
			$.ajax({
				url: path + "ajax/efectuarPagament.php?codiCurs="+codiCurs+"&titol="+titol+"&dni="+dni+"&nomTit="+nomTit+"&nomAl="+nomAl+"&import="+preu,
				cache: false,
				type: "GET",
				success: function(pagina) {
					$('#frm').submit();
				}
			});
		});
		$("#form_cancelar_dades").click(function(e) {
			var pagina = '<h1>Pagament ajornat</h1>';
			pagina += "<div class='d-flex flex-column tota-pagina'> ";
			pagina += "<div class='container'><div class='row'>";
			pagina += "<div class='d-flex flex-column sense-border align-items-center w-100 mb-4'>";
			pagina += "<p>Quan vulguis efectuar el pagament, podràs fer-ho mitjançant ";
			pagina += "l’enllaç que has rebut en el missatge de confirmació de la ";
			pagina += "inscripció a	l'adreça <span class='font-weight-bold email'>"
			pagina += email+"</span>. </p>";
			pagina += "<p>Si no trobes el missatge ni a la safata d'entrada ni al ";
			pagina += "correu brossa (<em>spam</em>), contacta amb nosaltres al ";
			pagina += "telèfon 972 21 75 65 o a ";
			pagina += "<span class='font-weight-bold email'>secretaria@prisma.cat</span>. </p>";
			pagina += "</div></div></div></div>";

			$('#cnt-pagament').html(pagina);
		});
	}
	else {
		$.ajax({
			url: path + "ajax/mostrarErrorEfectuarPagament.php",
			cache: false,
			type: "GET",
			success: function(pagina) {
				$('#cnt-pagament').html(pagina);
			}
		});
	}


}
efectuarPagament();

function adjustStyle() {
	screenWidth = parseInt($(this).width());
	//footer
	if (screenWidth < 425) {
		$('.sense-format > .panel').css('display', 'none');
		$('.accordion-footer').removeClass('active');
		$('.accordion-footer').click(function() {
			this.classList.toggle("active");
			var panel = this.nextElementSibling;
			if (panel.style.display === "block") {
				panel.style.display = "none";
				panel.style.maxHeight = null
			} else {
				panel.style.display = "block";
				panel.style.maxHeight = panel.scrollHeight + "px"
			}
		})
	} else {
		$('.accordion-footer').unbind();
		$('.accordion-footer').removeClass('active');
		$('.sense-format > .panel').css('display', 'block')
	}
}

$(function() {
	adjustStyle();

	$(window).resize(function() {
		adjustStyle();
	});
});

function afegirCSS() {
	$('body').append("<link rel='stylesheet' href='" + path + "css1600335587/efectuarPagament.min.css' />");
	$('body').append("<link rel='stylesheet' href='https://fonts.googleapis.com/css?family=Roboto:100,100i,300,400,500,700|Nunito+Sans&display=swap' />");
	$('body').append("<link rel='stylesheet' href='" + path + "css1600335587/font-awesome-prisma.min.css' />");
	$('body').append("<link rel='shortcut icon' type='image/x-icon' href='https://www.prisma.cat/favicon.ico'/>");
	$('body').append("<link rel='stylesheet' href='" + path + "css1600335587/404.min.css' />")
}
afegirCSS();

function openNav() {
	$(".navbarPrisma").css('width', '270px');
	$('.closebtn').css('display', 'block');
	$('.navBarPrisma').addClass('width-100');
	$("#pagina").addClass('sideNavBarPrismaObert');
	$("#pagina > .container").addClass('sideNavBarContainerPrismaObert');
	$('body').css('overflow-y', 'hidden')
}

function closeNav() {
	$(".navbarPrisma").css('width', '0');
	$('.closebtn').css('display', 'none');
	$('.navBarPrisma').removeClass('width-100');
	$("#pagina").removeClass('sideNavBarPrismaObert');
	$("#pagina > .container").removeClass('sideNavBarContainerPrismaObert');
	$('body').css('overflow-y', 'auto')
}
window.onscroll = function() {
	noPerdreHeader()
};

function noPerdreHeader() {
	if (document.body.scrollTop > 0 || document.documentElement.scrollTop > 0) {
		$('#top-menu').css('display', 'none');
		$('#nav-header').css('position', 'fixed');
		$('#nav-header').css('top', '0')
	} else {
		if (!(/Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i.test(navigator.userAgent)))
			$('#top-menu').css('display', 'block');
		$('#nav-header').css('position', 'inherit')
	}
}
